    16→package com.google.auto.common;
    17→
    18→import com.google.common.base.Equivalence;
    19→
    20→import java.util.List;
    21→
    22→import javax.lang.model.element.AnnotationMirror;
    23→import javax.lang.model.element.AnnotationValue;
    24→import javax.lang.model.type.TypeMirror;
    25→import javax.lang.model.util.SimpleAnnotationValueVisitor6;
    26→
    27→/**
    28→ * A utility class for working with {@link AnnotationValue} instances.
    29→ *
    30→ * @author Christian Gruber
    31→ */
    32→public final class AnnotationValues {
    33→  private static final Equivalence<AnnotationValue> ANNOTATION_VALUE_EQUIVALENCE =
    34→      new Equivalence<AnnotationValue>() {
    35→        @Override protected boolean doEquivalent(AnnotationValue left, AnnotationValue right) {
    36→          return left.accept(new SimpleAnnotationValueVisitor6<Boolean, AnnotationValue>() {
    37→            // LHS is not an annotation or array of annotation values, so just test equality.
    38→            @Override protected Boolean defaultAction(Object left, AnnotationValue right) {
    39→              return left.equals(right.accept(
    40→                  new SimpleAnnotationValueVisitor6<Object, Void>() {
    41→                    @Override protected Object defaultAction(Object object, Void unused) {
    42→                      return object;
    43→                    }
    44→                  }, null));
    45→            }
    46→
    47→            // LHS is an annotation mirror so test equivalence for RHS annotation mirrors
    48→            // and false for other types.
    49→            @Override public Boolean visitAnnotation(AnnotationMirror left, AnnotationValue right) {
    50→              return right.accept(
    51→                  new SimpleAnnotationValueVisitor6<Boolean, AnnotationMirror>() {
    52→                    @Override protected Boolean defaultAction(Object right, AnnotationMirror left) {
    53→                      return false; // Not an annotation mirror, so can't be equal to such.
    54→                    }
    55→                    @Override
    56→                    public Boolean visitAnnotation(AnnotationMirror right, AnnotationMirror left) {
    57→                      return AnnotationMirrors.equivalence().equivalent(left, right);
    58→                    }
    59→                  }, left);
    60→            }
    61→
    62→            // LHS is a list of annotation values have to collect-test equivalences, or false
    63→            // for any other types.
    64→            @Override
    65→            public Boolean visitArray(List<? extends AnnotationValue> left, AnnotationValue right) {
    66→              return right.accept(
    67→                  new SimpleAnnotationValueVisitor6<Boolean, List<? extends AnnotationValue>>() {
    68→                    @Override protected Boolean defaultAction(
    69→                        Object ignored, List<? extends AnnotationValue> alsoIgnored) {
    70→                      return false; // Not an annotation mirror, so can't be equal to such.
    71→                    }
    72→
    73→                    @SuppressWarnings("unchecked") // safe covariant cast
    74→                    @Override public Boolean visitArray(
    75→                        List<? extends AnnotationValue> right ,
    76→                        List<? extends AnnotationValue> left) {
    77→                      return AnnotationValues.equivalence().pairwise().equivalent(
    78→                          (List<AnnotationValue>) left, (List<AnnotationValue>) right);
    79→                    }
    80→                  }, left);
    81→            }
    82→
    83→            @Override
    84→            public Boolean visitType(TypeMirror left, AnnotationValue right) {
    85→              return right.accept(
    86→                  new SimpleAnnotationValueVisitor6<Boolean, TypeMirror>() {
    87→                    @Override protected Boolean defaultAction(
    88→                        Object ignored, TypeMirror alsoIgnored) {
    89→                      return false; // Not an annotation mirror, so can't be equal to such.
    90→                    }
    91→
    92→                    @Override public Boolean visitType(TypeMirror right, TypeMirror left) {
    93→                      return MoreTypes.equivalence().equivalent(left, right);
    94→                    }
    95→                  }, left);
    96→            }
    97→          }, right);
    98→        }
    99→
   100→        @Override protected int doHash(AnnotationValue value) {
   101→          return value.accept(new SimpleAnnotationValueVisitor6<Integer, Void>() {
   102→            @Override public Integer visitAnnotation(AnnotationMirror value, Void ignore) {
   103→              return AnnotationMirrors.equivalence().hash(value);
   104→            }
   105→
   106→            @SuppressWarnings("unchecked") // safe covariant cast
   107→            @Override public Integer visitArray(
   108→                List<? extends AnnotationValue> values, Void ignore) {
   109→              return AnnotationValues.equivalence().pairwise().hash((List<AnnotationValue>) values);
   110→            }
   111→
   112→            @Override public Integer visitType(TypeMirror value, Void ignore) {
   113→              return MoreTypes.equivalence().hash(value);
   114→            }
   115→
   116→            @Override protected Integer defaultAction(Object value, Void ignored) {
   117→              return value.hashCode();
   118→            }
   119→          }, null);
   120→        }
   121→      };
   122→
   123→  /**
   124→   * Returns an {@link Equivalence} for {@link AnnotationValue} as annotation values may
   125→   * contain {@link AnnotationMirror} instances some of whose implementations delegate
   126→   * equality tests to {@link Object#equals} whereas the documentation explicitly states
   127→   * that instance/reference equality is not the proper test.
   128→   *
   129→   * @see AnnotationMirrors#equivalence()
   130→   */
   131→  public static Equivalence<AnnotationValue> equivalence() {
   132→    return ANNOTATION_VALUE_EQUIVALENCE;
   133→  }
   134→
   135→  private AnnotationValues() {}
   136→}
