    16→package com.google.auto.common;
    17→
    18→import static com.google.auto.common.MoreElements.isAnnotationPresent;
    19→import static com.google.auto.common.SuperficialValidation.validateElement;
    20→import static com.google.common.base.Preconditions.checkNotNull;
    21→import static com.google.common.base.Preconditions.checkState;
    22→import static com.google.common.collect.Iterables.transform;
    23→import static com.google.common.collect.Multimaps.filterKeys;
    24→import static javax.lang.model.element.ElementKind.PACKAGE;
    25→import static javax.tools.Diagnostic.Kind.ERROR;
    26→
    27→import com.google.common.base.Ascii;
    28→import com.google.common.base.Function;
    29→import com.google.common.base.Optional;
    30→import com.google.common.base.Predicates;
    31→import com.google.common.collect.ImmutableList;
    32→import com.google.common.collect.ImmutableMap;
    33→import com.google.common.collect.ImmutableSet;
    34→import com.google.common.collect.ImmutableSetMultimap;
    35→import com.google.common.collect.LinkedHashMultimap;
    36→import com.google.common.collect.SetMultimap;
    37→import com.google.common.collect.Sets;
    38→
    39→import java.lang.annotation.Annotation;
    40→import java.util.Collection;
    41→import java.util.LinkedHashSet;
    42→import java.util.Map;
    43→import java.util.Map.Entry;
    44→import java.util.Objects;
    45→import java.util.Set;
    46→
    47→import javax.annotation.processing.AbstractProcessor;
    48→import javax.annotation.processing.Messager;
    49→import javax.annotation.processing.ProcessingEnvironment;
    50→import javax.annotation.processing.Processor;
    51→import javax.annotation.processing.RoundEnvironment;
    52→import javax.lang.model.element.Element;
    53→import javax.lang.model.element.ExecutableElement;
    54→import javax.lang.model.element.PackageElement;
    55→import javax.lang.model.element.TypeElement;
    56→import javax.lang.model.type.ErrorType;
    57→import javax.lang.model.util.Elements;
    58→import javax.lang.model.util.SimpleElementVisitor6;
    59→
    60→/**
    61→ * An abstract {@link Processor} implementation that defers processing of {@link Element}s to later
    62→ * rounds if they cannot be processed.
    63→ *
    64→ * <p>Subclasses put their processing logic in {@link ProcessingStep} implementations. The
    65→ * steps are passed to the processor by returning them in the {@link #initSteps()} method, and can
    66→ * access the {@link ProcessingEnvironment} using {@link #processingEnv}.
    67→ *
    68→ * Any logic that needs to happen once per round can be specified by overriding
    69→ * {@link #postProcess()}.
    70→ *
    71→ * <h3>Ill-formed elements are deferred</h3>
    72→ * Any annotated element whose nearest enclosing type is not well-formed is deferred, and not passed
    73→ * to any {@code ProcessingStep}. This helps processors to avoid many common pitfalls, such as
    74→ * {@link ErrorType} instances, {@link ClassCastException}s and badly coerced types.
    75→ *
    76→ * <p>A non-package element is considered well-formed if its type, type parameters, parameters,
    77→ * default values, supertypes, annotations, and enclosed elements are. Package elements are treated
    78→ * similarly, except that their enclosed elements are not validated. See
    79→ * {@link SuperficialValidation#validateElement(Element)} for details.
    80→ *
    81→ * <p>The primary disadvantage to this validation is that any element that forms a circular
    82→ * dependency with a type generated by another {@code BasicAnnotationProcessor} will never compile
    83→ * because the element will never be fully complete. All such compilations will fail with an error
    84→ * message on the offending type that describes the issue.
    85→ *
    86→ * <h3>Each {@code ProcessingStep} can defer elements</h3>
    87→ *
    88→ * <p>Each {@code ProcessingStep} can defer elements by including them in the set returned by
    89→ * {@link ProcessingStep#process(SetMultimap)}; elements deferred by a step will be passed back to
    90→ * that step in a later round of processing.
    91→ *
    92→ * <p>This feature is useful when one processor may depend on code generated by another,
    93→ * independent processor, in a way that isn't caught by the well-formedness check described above.
    94→ * For example, if an element {@code A} cannot be processed because processing it depends on the
    95→ * existence of some class {@code B}, then {@code A} should be deferred until a later round of
    96→ * processing, when {@code B} will have been generated by another processor.
    97→ *
    98→ * <p>If {@code A} directly references {@code B}, then the well-formedness check will correctly
    99→ * defer processing of {@code A} until {@code B} has been generated.
   100→ *
   101→ * <p>However, if {@code A} references {@code B} only indirectly (for example, from within a method
   102→ * body), then the well-formedness check will not defer processing {@code A}, but a processing step
   103→ * can reject {@code A}.
   104→ */
   105→public abstract class BasicAnnotationProcessor extends AbstractProcessor {
   106→
   107→  private final Set<ElementName> deferredElementNames = new LinkedHashSet<ElementName>();
   108→  private final SetMultimap<ProcessingStep, ElementName> elementsDeferredBySteps =
   109→      LinkedHashMultimap.create();
   110→  private final String processorName = getClass().getCanonicalName();
   111→
   112→  private Elements elements;
   113→  private Messager messager;
   114→  private ImmutableList<? extends ProcessingStep> steps;
   115→
   116→  @Override
   117→  public final synchronized void init(ProcessingEnvironment processingEnv) {
   118→    super.init(processingEnv);
   119→    this.elements = processingEnv.getElementUtils();
   120→    this.messager = processingEnv.getMessager();
   121→    this.steps = ImmutableList.copyOf(initSteps());
   122→  }
   123→
   124→  /**
   125→   * Creates {@linkplain ProcessingStep processing steps} for this processor.
   126→   * {@link #processingEnv} is guaranteed to be set when this method is invoked.
   127→   */
   128→  protected abstract Iterable<? extends ProcessingStep> initSteps();
   129→
   130→  /** An optional hook for logic to be executed at the end of each round. */
   131→  protected void postProcess() {}
   132→
   133→  private ImmutableSet<? extends Class<? extends Annotation>> getSupportedAnnotationClasses() {
   134→    checkState(steps != null);
   135→    ImmutableSet.Builder<Class<? extends Annotation>> builder = ImmutableSet.builder();
   136→    for (ProcessingStep step : steps) {
   137→      builder.addAll(step.annotations());
   138→    }
   139→    return builder.build();
   140→  }
   141→
   142→  /**
   143→   * Returns the set of supported annotation types as a  collected from registered
   144→   * {@linkplain ProcessingStep processing steps}.
   145→   */
   146→  @Override
   147→  public final ImmutableSet<String> getSupportedAnnotationTypes() {
   148→    ImmutableSet.Builder<String> builder = ImmutableSet.builder();
   149→    for (Class<? extends Annotation> annotationClass : getSupportedAnnotationClasses()) {
   150→      builder.add(annotationClass.getCanonicalName());
   151→    }
   152→    return builder.build();
   153→  }
   154→
   155→  @Override
   156→  public final boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
   157→    checkState(elements != null);
   158→    checkState(messager != null);
   159→    checkState(steps != null);
   160→
   161→    ImmutableMap<String, Optional<? extends Element>> deferredElements = deferredElements();
   162→
   163→    deferredElementNames.clear();
   164→
   165→    // If this is the last round, report all of the missing elements
   166→    if (roundEnv.processingOver()) {
   167→      reportMissingElements(deferredElements, elementsDeferredBySteps.values());
   168→      return false;
   169→    }
   170→
   171→    process(validElements(deferredElements, roundEnv));
   172→
   173→    postProcess();
   174→
   175→    return false;
   176→  }
   177→
   178→  /**
   179→   * Returns the previously deferred elements.
   180→   */
   181→  private ImmutableMap<String, Optional<? extends Element>> deferredElements() {
   182→    ImmutableMap.Builder<String, Optional<? extends Element>> deferredElements =
   183→        ImmutableMap.builder();
   184→    for (ElementName elementName : deferredElementNames) {
   185→      deferredElements.put(elementName.name(), elementName.getElement(elements));
   186→    }
   187→    return deferredElements.build();
   188→  }
   189→
   190→  private void reportMissingElements(
   191→      Map<String, ? extends Optional<? extends Element>> missingElements,
   192→      Collection<ElementName> missingElementNames) {
   193→    if (!missingElementNames.isEmpty()) {
   194→      ImmutableMap.Builder<String, Optional<? extends Element>> allMissingElements =
   195→          ImmutableMap.builder();
   196→      allMissingElements.putAll(missingElements);
   197→      for (ElementName missingElement : missingElementNames) {
   198→        if (!missingElements.containsKey(missingElement.name())) {
   199→          allMissingElements.put(missingElement.name(), missingElement.getElement(elements));
   200→        }
   201→      }
   202→      missingElements = allMissingElements.build();
   203→    }
   204→    for (Entry<String, ? extends Optional<? extends Element>> missingElementEntry :
   205→        missingElements.entrySet()) {
   206→      Optional<? extends Element> missingElement = missingElementEntry.getValue();
   207→      if (missingElement.isPresent()) {
   208→        processingEnv
   209→            .getMessager()
   210→            .printMessage(
   211→                ERROR,
   212→                processingErrorMessage(
   213→                    "this " + Ascii.toLowerCase(missingElement.get().getKind().name())),
   214→                missingElement.get());
   215→      } else {
   216→        processingEnv
   217→            .getMessager()
   218→            .printMessage(ERROR, processingErrorMessage(missingElementEntry.getKey()));
   219→      }
   220→    }
   221→  }
   222→
   223→  private String processingErrorMessage(String target) {
   224→    return String.format(
   225→        "%s was unable to process %s because not all of its dependencies could be resolved. Check "
   226→            + "for compilation errors or a circular dependency with generated code.",
   227→        processorName,
   228→        target);
   229→  }
   230→
   231→  /**
   232→   * Returns the valid annotated elements contained in all of the deferred elements. If none are
   233→   * found for a deferred element, defers it again.
   234→   */
   235→  private ImmutableSetMultimap<Class<? extends Annotation>, Element> validElements(
   236→      ImmutableMap<String, Optional<? extends Element>> deferredElements,
   237→      RoundEnvironment roundEnv) {
   238→    ImmutableSetMultimap.Builder<Class<? extends Annotation>, Element>
   239→        deferredElementsByAnnotationBuilder = ImmutableSetMultimap.builder();
   240→    for (Entry<String, Optional<? extends Element>> deferredTypeElementEntry :
   241→        deferredElements.entrySet()) {
   242→      Optional<? extends Element> deferredElement = deferredTypeElementEntry.getValue();
   243→      if (deferredElement.isPresent()) {
   244→        findAnnotatedElements(
   245→            deferredElement.get(),
   246→            getSupportedAnnotationClasses(),
   247→            deferredElementsByAnnotationBuilder);
   248→      } else {
   249→        deferredElementNames.add(ElementName.forTypeName(deferredTypeElementEntry.getKey()));
   250→      }
   251→    }
   252→
   253→    ImmutableSetMultimap<Class<? extends Annotation>, Element> deferredElementsByAnnotation =
   254→        deferredElementsByAnnotationBuilder.build();
   255→
   256→    ImmutableSetMultimap.Builder<Class<? extends Annotation>, Element> validElements =
   257→        ImmutableSetMultimap.builder();
   258→
   259→    Set<ElementName> validElementNames = new LinkedHashSet<ElementName>();
   260→
   261→    // Look at the elements we've found and the new elements from this round and validate them.
   262→    for (Class<? extends Annotation> annotationClass : getSupportedAnnotationClasses()) {
   263→      // This should just call roundEnv.getElementsAnnotatedWith(Class) directly, but there is a bug
   264→      // in some versions of eclipse that cause that method to crash.
   265→      TypeElement annotationType = elements.getTypeElement(annotationClass.getCanonicalName());
   266→      Set<? extends Element> elementsAnnotatedWith =
   267→          (annotationType == null)
   268→              ? ImmutableSet.<Element>of()
   269→              : roundEnv.getElementsAnnotatedWith(annotationType);
   270→      for (Element annotatedElement :
   271→          Sets.union(elementsAnnotatedWith, deferredElementsByAnnotation.get(annotationClass))) {
   272→        if (annotatedElement.getKind().equals(PACKAGE)) {
   273→          PackageElement annotatedPackageElement = (PackageElement) annotatedElement;
   274→          ElementName annotatedPackageName =
   275→              ElementName.forPackageName(annotatedPackageElement.getQualifiedName().toString());
   276→          boolean validPackage =
   277→              validElementNames.contains(annotatedPackageName)
   278→                  || (!deferredElementNames.contains(annotatedPackageName)
   279→                      && validateElement(annotatedPackageElement));
   280→          if (validPackage) {
   281→            validElements.put(annotationClass, annotatedPackageElement);
   282→            validElementNames.add(annotatedPackageName);
   283→          } else {
   284→            deferredElementNames.add(annotatedPackageName);
   285→          }
   286→        } else {
   287→          TypeElement enclosingType = getEnclosingType(annotatedElement);
   288→          ElementName enclosingTypeName =
   289→              ElementName.forTypeName(enclosingType.getQualifiedName().toString());
   290→          boolean validEnclosingType =
   291→              validElementNames.contains(enclosingTypeName)
   292→                  || (!deferredElementNames.contains(enclosingTypeName)
   293→                      && validateElement(enclosingType));
   294→          if (validEnclosingType) {
   295→            validElements.put(annotationClass, annotatedElement);
   296→            validElementNames.add(enclosingTypeName);
   297→          } else {
   298→            deferredElementNames.add(enclosingTypeName);
   299→          }
   300→        }
   301→      }
   302→    }
   303→
   304→    return validElements.build();
   305→  }
   306→
   307→  /** Processes the valid elements, including those previously deferred by each step. */
   308→  private void process(ImmutableSetMultimap<Class<? extends Annotation>, Element> validElements) {
   309→    for (ProcessingStep step : steps) {
   310→      ImmutableSetMultimap<Class<? extends Annotation>, Element> stepElements =
   311→          new ImmutableSetMultimap.Builder<Class<? extends Annotation>, Element>()
   312→              .putAll(indexByAnnotation(elementsDeferredBySteps.get(step)))
   313→              .putAll(filterKeys(validElements, Predicates.<Object>in(step.annotations())))
   314→              .build();
   315→      if (stepElements.isEmpty()) {
   316→        elementsDeferredBySteps.removeAll(step);
   317→      } else {
   318→        Set<Element> rejectedElements = step.process(stepElements);
   319→        elementsDeferredBySteps.replaceValues(
   320→            step,
   321→            transform(
   322→                rejectedElements,
   323→                new Function<Element, ElementName>() {
   324→                  @Override
   325→                  public ElementName apply(Element element) {
   326→                    return ElementName.forAnnotatedElement(element);
   327→                  }
   328→                }));
   329→      }
   330→    }
   331→  }
   332→
   333→  private ImmutableSetMultimap<Class<? extends Annotation>, Element> indexByAnnotation(
   334→      Set<ElementName> annotatedElements) {
   335→    ImmutableSet<? extends Class<? extends Annotation>> supportedAnnotationClasses =
   336→        getSupportedAnnotationClasses();
   337→    ImmutableSetMultimap.Builder<Class<? extends Annotation>, Element> deferredElements =
   338→        ImmutableSetMultimap.builder();
   339→    for (ElementName elementName : annotatedElements) {
   340→      Optional<? extends Element> element = elementName.getElement(elements);
   341→      if (element.isPresent()) {
   342→        findAnnotatedElements(element.get(), supportedAnnotationClasses, deferredElements);
   343→      }
   344→    }
   345→    return deferredElements.build();
   346→  }
   347→
   348→  /**
   349→   * Adds {@code element} and its enclosed elements to {@code annotatedElements} if they are
   350→   * annotated with any annotations in {@code annotationClasses}. Does not traverse to member types
   351→   * of {@code element}, so that if {@code Outer} is passed in the example below, looking for
   352→   * {@code @X}, then {@code Outer}, {@code Outer.foo}, and {@code Outer.foo()} will be added to the
   353→   * multimap, but neither {@code Inner} nor its members will.
   354→   *
   355→   * <pre><code>
   356→   *   {@literal @}X class Outer {
   357→   *     {@literal @}X Object foo;
   358→   *     {@literal @}X void foo() {}
   359→   *     {@literal @}X static class Inner {
   360→   *       {@literal @}X Object bar;
   361→   *       {@literal @}X void bar() {}
   362→   *     }
   363→   *   }
   364→   * </code></pre>
   365→   */
   366→  private static void findAnnotatedElements(
   367→      Element element,
   368→      ImmutableSet<? extends Class<? extends Annotation>> annotationClasses,
   369→      ImmutableSetMultimap.Builder<Class<? extends Annotation>, Element> annotatedElements) {
   370→    for (Element enclosedElement : element.getEnclosedElements()) {
   371→      if (!enclosedElement.getKind().isClass() && !enclosedElement.getKind().isInterface()) {
   372→        findAnnotatedElements(enclosedElement, annotationClasses, annotatedElements);
   373→      }
   374→    }
   375→
   376→    // element.getEnclosedElements() does NOT return parameter elements
   377→    if (element instanceof ExecutableElement) {
   378→      for (Element parameterElement : ((ExecutableElement) element).getParameters()) {
   379→        findAnnotatedElements(parameterElement, annotationClasses, annotatedElements);
   380→      }
   381→    }
   382→    for (Class<? extends Annotation> annotationClass : annotationClasses) {
   383→      if (isAnnotationPresent(element, annotationClass)) {
   384→        annotatedElements.put(annotationClass, element);
   385→      }
   386→    }
   387→  }
   388→
   389→  /**
   390→   * Returns the nearest enclosing {@link TypeElement} to the current element, throwing
   391→   * an {@link IllegalArgumentException} if the provided {@link Element} is a
   392→   * {@link PackageElement} or is otherwise not enclosed by a type.
   393→   */
   394→  // TODO(cgruber) move to MoreElements and make public.
   395→  private static TypeElement getEnclosingType(Element element) {
   396→    return element.accept(new SimpleElementVisitor6<TypeElement, Void>() {
   397→      @Override protected TypeElement defaultAction(Element e, Void p) {
   398→        return e.getEnclosingElement().accept(this, p);
   399→      }
   400→
   401→      @Override public TypeElement visitType(TypeElement e, Void p) {
   402→        return e;
   403→      }
   404→
   405→      @Override public TypeElement visitPackage(PackageElement e, Void p) {
   406→        throw new IllegalArgumentException();
   407→      }
   408→    }, null);
   409→  }
