   121→  private static final TypeVisitor<Boolean, Void> TYPE_VALIDATING_VISITOR =
   122→      new SimpleTypeVisitor6<Boolean, Void>() {
   123→        @Override
   124→        protected Boolean defaultAction(TypeMirror t, Void p) {
   125→          return true;
   126→        }
   127→
   128→        @Override
   129→        public Boolean visitArray(ArrayType t, Void p) {
   130→          return validateType(t.getComponentType());
   131→        }
   132→
   133→        @Override
   134→        public Boolean visitDeclared(DeclaredType t, Void p) {
   135→          return validateTypes(t.getTypeArguments());
   136→        }
   137→
   138→        @Override
   139→        public Boolean visitError(ErrorType t, Void p) {
   140→          return false;
   141→        }
   142→
   143→        @Override
   144→        public Boolean visitUnknown(TypeMirror t, Void p) {
   145→          // just make the default choice for unknown types
   146→          return defaultAction(t, p);
   147→        }
   148→
   149→        @Override
   150→        public Boolean visitWildcard(WildcardType t, Void p) {
   151→          TypeMirror extendsBound = t.getExtendsBound();
   152→          TypeMirror superBound = t.getSuperBound();
   153→          return (extendsBound == null || validateType(extendsBound))
   154→              && (superBound == null || validateType(superBound));
   155→        }
   156→
   157→        @Override
   158→        public Boolean visitExecutable(ExecutableType t, Void p) {
   159→          return validateTypes(t.getParameterTypes())
   160→              && validateType(t.getReturnType())
   161→              && validateTypes(t.getThrownTypes())
   162→              && validateTypes(t.getTypeVariables());
   163→        }
   164→      };
   165→
   166→  private static boolean validateType(TypeMirror type) {
   167→    return type.accept(TYPE_VALIDATING_VISITOR, null);
   168→  }
   169→
   170→  private static boolean validateAnnotations(
   171→      Iterable<? extends AnnotationMirror> annotationMirrors) {
   172→    for (AnnotationMirror annotationMirror : annotationMirrors) {
   173→      if (!validateAnnotation(annotationMirror)) {
   174→        return false;
   175→      }
   176→    }
   177→    return true;
   178→  }
   179→
   180→  private static boolean validateAnnotation(AnnotationMirror annotationMirror) {
   181→    return validateType(annotationMirror.getAnnotationType())
   182→        && validateAnnotationValues(annotationMirror.getElementValues());
   183→  }
   184→
   185→  @SuppressWarnings("unused")
   186→  private static boolean validateAnnotationValues(
   187→      Map<? extends ExecutableElement, ? extends AnnotationValue> valueMap) {
   188→    for (Map.Entry<? extends ExecutableElement, ? extends AnnotationValue> valueEntry :
   189→        valueMap.entrySet()) {
   190→      TypeMirror expectedType = valueEntry.getKey().getReturnType();
   191→      if (!validateAnnotationValue(valueEntry.getValue(), expectedType)) {
   192→        return false;
   193→      }
   194→    }
   195→    return true;
   196→  }
   197→
   198→  private static final AnnotationValueVisitor<Boolean, TypeMirror> VALUE_VALIDATING_VISITOR =
   199→      new SimpleAnnotationValueVisitor6<Boolean, TypeMirror>() {
   200→        @Override protected Boolean defaultAction(Object o, TypeMirror expectedType) {
   201→          return MoreTypes.isTypeOf(o.getClass(), expectedType);
   202→        }
   203→
   204→        @Override public Boolean visitUnknown(AnnotationValue av, TypeMirror expectedType) {
   205→          // just take the default action for the unknown
   206→          return defaultAction(av, expectedType);
   207→        }
   208→
   209→        @Override public Boolean visitAnnotation(AnnotationMirror a, TypeMirror expectedType) {
   210→          return MoreTypes.equivalence().equivalent(a.getAnnotationType(), expectedType)
   211→              && validateAnnotation(a);
   212→        }
   213→
   214→        @Override
   215→        public Boolean visitArray(List<? extends AnnotationValue> values, TypeMirror expectedType) {
   216→          if (!expectedType.getKind().equals(TypeKind.ARRAY)) {
   217→            return false;
   218→          }
   219→          try {
   220→            expectedType = MoreTypes.asArray(expectedType).getComponentType();
   221→          } catch (IllegalArgumentException e) {
   222→            return false; // Not an array expected, ergo invalid.
   223→          }
   224→          for (AnnotationValue value : values) {
   225→            if (!value.accept(this, expectedType)) {
   226→              return false;
   227→            }
   228→          }
   229→          return true;
   230→        }
   231→
   232→        @Override
   233→        public Boolean visitEnumConstant(VariableElement enumConstant, TypeMirror expectedType) {
   234→          return MoreTypes.equivalence().equivalent(enumConstant.asType(), expectedType)
   235→              && validateElement(enumConstant);
   236→        }
   237→
   238→        @Override public Boolean visitType(TypeMirror type, TypeMirror ignored) {
   239→          // We could check assignability here, but would require a Types instance. Since this
   240→          // isn't really the sort of thing that shows up in a bad AST from upstream compilation
   241→          // we ignore the expected type and just validate the type.  It might be wrong, but
   242→          // it's valid.
   243→          return validateType(type);
   244→        }
   245→
   246→        @Override public Boolean visitBoolean(boolean b, TypeMirror expectedType) {
   247→          return MoreTypes.isTypeOf(Boolean.TYPE, expectedType);
   248→        }
   249→
   250→        @Override public Boolean visitByte(byte b, TypeMirror expectedType) {
   251→          return MoreTypes.isTypeOf(Byte.TYPE, expectedType);
   252→        }
   253→
   254→        @Override public Boolean visitChar(char c, TypeMirror expectedType) {
   255→          return MoreTypes.isTypeOf(Character.TYPE, expectedType);
   256→        }
   257→
   258→        @Override public Boolean visitDouble(double d, TypeMirror expectedType) {
   259→          return MoreTypes.isTypeOf(Double.TYPE, expectedType);
   260→        }
   261→
   262→        @Override public Boolean visitFloat(float f, TypeMirror expectedType) {
   263→          return MoreTypes.isTypeOf(Float.TYPE, expectedType);
   264→        }
   265→
   266→        @Override public Boolean visitInt(int i, TypeMirror expectedType) {
   267→          return MoreTypes.isTypeOf(Integer.TYPE, expectedType);
   268→        }
   269→
   270→        @Override public Boolean visitLong(long l, TypeMirror expectedType) {
   271→          return MoreTypes.isTypeOf(Long.TYPE, expectedType);
   272→        }
   273→
   274→        @Override public Boolean visitShort(short s, TypeMirror expectedType) {
   275→          return MoreTypes.isTypeOf(Short.TYPE, expectedType);
   276→        }
   277→      };
   278→
   279→  private static boolean validateAnnotationValue(
   280→      AnnotationValue annotationValue, TypeMirror expectedType) {
   281→    return annotationValue.accept(VALUE_VALIDATING_VISITOR, expectedType);
   282→  }
   283→}
