    88→  // So EQUAL_VISITOR can be a singleton, we maintain visiting state, in particular which types
    89→  // have been seen already, in this object.
    90→  // The logic for handling recursive types like Comparable<T extends Comparable<T>> is very tricky.
    91→  // If we're not careful we'll end up with an infinite recursion. So we record the types that
    92→  // we've already seen during the recursion, and if we see the same pair of types again we just
    93→  // return true provisionally. But "the same pair of types" is itself poorly-defined. We can't
    94→  // just say that it is an equal pair of TypeMirrors, because of course if we knew how to
    95→  // determine that then we wouldn't need the complicated type visitor at all. On the other hand,
    96→  // we can't say that it is an identical pair of TypeMirrors either, because there's no
    97→  // guarantee that the TypeMirrors for the two Ts in Comparable<T extends Comparable<T>> will be
    98→  // represented by the same object, and indeed with the Eclipse compiler they aren't. We could
    99→  // compare the corresponding Elements, since equality is well-defined there, but that's not enough
   100→  // either, because the Element for Set<Object> is the same as the one for Set<String>. So we
   101→  // approximate by comparing the Elements and, if there are any type arguments, requiring them to
   102→  // be identical. This may not be foolproof either but it is sufficient for all the cases we've
   103→  // encountered so far.
   104→  private static final class EqualVisitorParam {
   105→    TypeMirror type;
   106→    Set<ComparedElements> visiting;
   107→  }
   108→
   109→  private static class ComparedElements {
   110→    final Element a;
   111→    final ImmutableList<TypeMirror> aArguments;
   112→    final Element b;
   113→    final ImmutableList<TypeMirror> bArguments;
   114→
   115→    ComparedElements(
   116→        Element a,
   117→        ImmutableList<TypeMirror> aArguments,
   118→        Element b,
   119→        ImmutableList<TypeMirror> bArguments) {
   120→      this.a = a;
   121→      this.aArguments = aArguments;
   122→      this.b = b;
   123→      this.bArguments = bArguments;
   124→    }
   125→
   126→    @Override
   127→    public boolean equals(Object o) {
   128→      if (o instanceof ComparedElements) {
   129→        ComparedElements that = (ComparedElements) o;
   130→        int nArguments = aArguments.size();
   131→        if (!this.a.equals(that.a)
   132→            || !this.b.equals(that.b)
   133→            || nArguments != bArguments.size()) {
   134→          // The arguments must be the same size, but we check anyway.
   135→          return false;
   136→        }
   137→        for (int i = 0; i < nArguments; i++) {
   138→          if (aArguments.get(i) != bArguments.get(i)) {
   139→            return false;
   140→          }
   141→        }
   142→        return true;
   143→      } else {
   144→        return false;
   145→      }
   146→    }
   147→
   148→    @Override
   149→    public int hashCode() {
   150→      return a.hashCode() * 31 + b.hashCode();
   151→    }
   152→  }
   153→
   154→  private static final TypeVisitor<Boolean, EqualVisitorParam> EQUAL_VISITOR =
   155→      new SimpleTypeVisitor6<Boolean, EqualVisitorParam>() {
   156→        @Override
   157→        protected Boolean defaultAction(TypeMirror a, EqualVisitorParam p) {
   158→          return a.getKind().equals(p.type.getKind());
   159→        }
   160→
   161→        @Override
   162→        public Boolean visitArray(ArrayType a, EqualVisitorParam p) {
   163→          if (p.type.getKind().equals(ARRAY)) {
   164→            ArrayType b = (ArrayType) p.type;
   165→            return equal(a.getComponentType(), b.getComponentType(), p.visiting);
   166→          }
   167→          return false;
   168→        }
   169→
   170→        @Override
   171→        public Boolean visitDeclared(DeclaredType a, EqualVisitorParam p) {
   172→          if (p.type.getKind().equals(DECLARED)) {
   173→            DeclaredType b = (DeclaredType) p.type;
   174→            Element aElement = a.asElement();
   175→            Element bElement = b.asElement();
   176→            Set<ComparedElements> newVisiting = visitingSetPlus(
   177→                p.visiting, aElement, a.getTypeArguments(), bElement, b.getTypeArguments());
   178→            if (newVisiting.equals(p.visiting)) {
   179→              // We're already visiting this pair of elements.
   180→              // This can happen for example with Enum in Enum<E extends Enum<E>>. Return a
   181→              // provisional true value since if the Elements are not in fact equal the original
   182→              // visitor of Enum will discover that. We have to check both Elements being compared
   183→              // though to avoid missing the fact that one of the types being compared
   184→              // differs at exactly this point.
   185→              return true;
   186→            }
   187→            return aElement.equals(bElement)
   188→                && equal(a.getEnclosingType(), a.getEnclosingType(), newVisiting)
   189→                && equalLists(a.getTypeArguments(), b.getTypeArguments(), newVisiting);
   190→
   191→          }
   192→          return false;
   193→        }
   194→
   195→        @Override
   196→        public Boolean visitError(ErrorType a, EqualVisitorParam p) {
   197→          return a.equals(p.type);
   198→        }
   199→
   200→        @Override
   201→        public Boolean visitExecutable(ExecutableType a, EqualVisitorParam p) {
   202→          if (p.type.getKind().equals(EXECUTABLE)) {
   203→            ExecutableType b = (ExecutableType) p.type;
   204→            return equalLists(a.getParameterTypes(), b.getParameterTypes(), p.visiting)
   205→                && equal(a.getReturnType(), b.getReturnType(), p.visiting)
   206→                && equalLists(a.getThrownTypes(), b.getThrownTypes(), p.visiting)
   207→                && equalLists(a.getTypeVariables(), b.getTypeVariables(), p.visiting);
   208→          }
   209→          return false;
   210→        }
   211→
   212→        @Override
   213→        public Boolean visitTypeVariable(TypeVariable a, EqualVisitorParam p) {
   214→          if (p.type.getKind().equals(TYPEVAR)) {
   215→            TypeVariable b = (TypeVariable) p.type;
   216→            TypeParameterElement aElement = (TypeParameterElement) a.asElement();
   217→            TypeParameterElement bElement = (TypeParameterElement) b.asElement();
   218→            Set<ComparedElements> newVisiting = visitingSetPlus(p.visiting, aElement, bElement);
   219→            if (newVisiting.equals(p.visiting)) {
   220→              // We're already visiting this pair of elements.
   221→              // This can happen with our friend Eclipse when looking at <T extends Comparable<T>>.
   222→              // It incorrectly reports the upper bound of T as T itself.
   223→              return true;
   224→            }
   225→            // We use aElement.getBounds() instead of a.getUpperBound() to avoid having to deal with
   226→            // the different way intersection types (like <T extends Number & Comparable<T>>) are
   227→            // represented before and after Java 8. We do have an issue that this code may consider
   228→            // that <T extends Foo & Bar> is different from <T extends Bar & Foo>, but it's very
   229→            // hard to avoid that, and not likely to be much of a problem in practice.
   230→            return equalLists(aElement.getBounds(), bElement.getBounds(), newVisiting)
   231→                && equal(a.getLowerBound(), b.getLowerBound(), newVisiting)
   232→                && a.asElement().getSimpleName().equals(b.asElement().getSimpleName());
   233→          }
   234→          return false;
   235→        }
   236→
   237→        @Override
   238→        public Boolean visitWildcard(WildcardType a, EqualVisitorParam p) {
   239→          if (p.type.getKind().equals(WILDCARD)) {
   240→            WildcardType b = (WildcardType) p.type;
   241→            return equal(a.getExtendsBound(), b.getExtendsBound(), p.visiting)
   242→                && equal(a.getSuperBound(), b.getSuperBound(), p.visiting);
   243→          }
   244→          return false;
   245→        }
   246→
   247→        @Override
   248→        public Boolean visitUnknown(TypeMirror a, EqualVisitorParam p) {
   249→          throw new UnsupportedOperationException();
   250→        }
   251→
   252→        private Set<ComparedElements> visitingSetPlus(
   253→            Set<ComparedElements> visiting, Element a, Element b) {
   254→          ImmutableList<TypeMirror> noArguments = ImmutableList.of();
   255→          return visitingSetPlus(visiting, a, noArguments, b, noArguments);
   256→        }
   257→
   258→        private Set<ComparedElements> visitingSetPlus(
   259→            Set<ComparedElements> visiting,
   260→            Element a, List<? extends TypeMirror> aArguments,
   261→            Element b, List<? extends TypeMirror> bArguments) {
   262→          ComparedElements comparedElements =
   263→              new ComparedElements(
   264→                  a, ImmutableList.<TypeMirror>copyOf(aArguments),
   265→                  b, ImmutableList.<TypeMirror>copyOf(bArguments));
   266→          Set<ComparedElements> newVisiting = new HashSet<ComparedElements>(visiting);
   267→          newVisiting.add(comparedElements);
