   272→  private static final Class<?> INTERSECTION_TYPE;
   273→  private static final Method GET_BOUNDS;
   274→  static {
   275→    Class<?> c;
   276→    Method m;
   277→    try {
   278→      c = Class.forName("javax.lang.model.type.IntersectionType");
   279→      m = c.getMethod("getBounds");
   280→    } catch (Exception e) {
   281→      c = null;
   282→      m = null;
   283→    }
   284→    INTERSECTION_TYPE = c;
   285→    GET_BOUNDS = m;
   286→  }
