   288→  private static boolean equal(TypeMirror a, TypeMirror b, Set<ComparedElements> visiting) {
   289→    // TypeMirror.equals is not guaranteed to return true for types that are equal, but we can
   290→    // assume that if it does return true then the types are equal. This check also avoids getting
   291→    // stuck in infinite recursion when Eclipse decrees that the upper bound of the second K in
   292→    // <K extends Comparable<K>> is a distinct but equal K.
   293→    // The javac implementation of ExecutableType, at least in some versions, does not take thrown
   294→    // exceptions into account in its equals implementation, so avoid this optimization for
   295→    // ExecutableType.
   296→    if (Objects.equal(a, b) && !(a instanceof ExecutableType)) {
   297→      return true;
   298→    }
   299→    EqualVisitorParam p = new EqualVisitorParam();
   300→    p.type = b;
   301→    p.visiting = visiting;
   302→    if (INTERSECTION_TYPE != null) {
   303→      if (isIntersectionType(a)) {
   304→        return equalIntersectionTypes(a, b, visiting);
   305→      } else if (isIntersectionType(b)) {
   306→        return false;
   307→      }
   308→    }
   309→    return (a == b) || (a != null && b != null && a.accept(EQUAL_VISITOR, p));
   310→  }
   311→
   312→  private static boolean isIntersectionType(TypeMirror t) {
   313→    return t != null && t.getKind().name().equals("INTERSECTION");
   314→  }
   315→
   316→  // The representation of an intersection type, as in <T extends Number & Comparable<T>>, changed
   317→  // between Java 7 and Java 8. In Java 7 it was modeled as a fake DeclaredType, and our logic
   318→  // for DeclaredType does the right thing. In Java 8 it is modeled as a new type IntersectionType.
   319→  // In order for our code to run on Java 7 (and Java 6) we can't even mention IntersectionType,
   320→  // so we can't override visitIntersectionType(IntersectionType). Instead, we discover through
   321→  // reflection whether IntersectionType exists, and if it does we extract the bounds of the
   322→  // intersection ((Number, Comparable<T>) in the example) and compare them directly.
   323→  @SuppressWarnings("unchecked")
   324→  private static boolean equalIntersectionTypes(
   325→      TypeMirror a, TypeMirror b, Set<ComparedElements> visiting) {
   326→    if (!isIntersectionType(b)) {
   327→      return false;
   328→    }
   329→    List<? extends TypeMirror> aBounds;
   330→    List<? extends TypeMirror> bBounds;
   331→    try {
   332→      aBounds = (List<? extends TypeMirror>) GET_BOUNDS.invoke(a);
   333→      bBounds = (List<? extends TypeMirror>) GET_BOUNDS.invoke(b);
   334→    } catch (Exception e) {
   335→      throw Throwables.propagate(e);
   336→    }
   337→    return equalLists(aBounds, bBounds, visiting);
   338→  }
   339→
   340→  private static boolean equalLists(
   341→      List<? extends TypeMirror> a, List<? extends TypeMirror> b,
   342→      Set<ComparedElements> visiting) {
   343→    int size = a.size();
   344→    if (size != b.size()) {
   345→      return false;
   346→    }
   347→    // Use iterators in case the Lists aren't RandomAccess
   348→    Iterator<? extends TypeMirror> aIterator = a.iterator();
   349→    Iterator<? extends TypeMirror> bIterator = b.iterator();
   350→    while (aIterator.hasNext()) {
   351→      if (!bIterator.hasNext()) {
   352→        return false;
   353→      }
   354→      TypeMirror nextMirrorA = aIterator.next();
   355→      TypeMirror nextMirrorB = bIterator.next();
   356→      if (!equal(nextMirrorA, nextMirrorB, visiting)) {
   357→        return false;
   358→      }
   359→    }
   360→    return !aIterator.hasNext();
   361→  }
