   462→  /**
   463→   * Returns the set of {@linkplain TypeElement types} that are referenced by the given
   464→   * {@link TypeMirror}.
   465→   */
   466→  public static ImmutableSet<TypeElement> referencedTypes(TypeMirror type) {
   467→    checkNotNull(type);
   468→    ImmutableSet.Builder<TypeElement> elements = ImmutableSet.builder();
   469→    type.accept(new SimpleTypeVisitor6<Void, ImmutableSet.Builder<TypeElement>>() {
   470→      @Override
   471→      public Void visitArray(ArrayType t, Builder<TypeElement> p) {
   472→        t.getComponentType().accept(this, p);
   473→        return null;
   474→      }
   475→
   476→      @Override
   477→      public Void visitDeclared(DeclaredType t, Builder<TypeElement> p) {
   478→        p.add(MoreElements.asType(t.asElement()));
   479→        for (TypeMirror typeArgument : t.getTypeArguments()) {
   480→          typeArgument.accept(this, p);
   481→        }
   482→        return null;
   483→      }
   484→
   485→      @Override
   486→      public Void visitTypeVariable(TypeVariable t, Builder<TypeElement> p) {
   487→        t.getLowerBound().accept(this, p);
   488→        t.getUpperBound().accept(this, p);
   489→        return null;
   490→      }
   491→
   492→      @Override
   493→      public Void visitWildcard(WildcardType t, Builder<TypeElement> p) {
   494→        TypeMirror extendsBound = t.getExtendsBound();
   495→        if (extendsBound != null) {
   496→          extendsBound.accept(this, p);
   497→        }
   498→        TypeMirror superBound = t.getSuperBound();
   499→        if (superBound != null) {
   500→          superBound.accept(this, p);
   501→        }
   502→        return null;
   503→      }
   504→    }, elements);
   505→    return elements.build();
   506→  }
