   755→  /**
   756→   * Returns the non-object superclass of the type with the proper type parameters.
   757→   * An absent Optional is returned if there is no non-Object superclass.
   758→   */
   759→  public static Optional<DeclaredType> nonObjectSuperclass(final Types types, Elements elements,
   760→      DeclaredType type) {
   761→    checkNotNull(types);
   762→    checkNotNull(elements);
   763→    checkNotNull(type);
   764→
   765→    final TypeMirror objectType =
   766→        elements.getTypeElement(Object.class.getCanonicalName()).asType();
   767→    // It's guaranteed there's only a single CLASS superclass because java doesn't have multiple
   768→    // class inheritance.
   769→    TypeMirror superclass = getOnlyElement(FluentIterable.from(types.directSupertypes(type))
   770→        .filter(new Predicate<TypeMirror>() {
   771→          @Override public boolean apply(TypeMirror input) {
   772→           return input.getKind().equals(TypeKind.DECLARED)
   773→               && (MoreElements.asType(
   774→                     MoreTypes.asDeclared(input).asElement())).getKind().equals(ElementKind.CLASS)
   775→               && !types.isSameType(objectType, input);
   776→          }
   777→        }), null);
   778→    return superclass != null
   779→        ? Optional.of(MoreTypes.asDeclared(superclass))
   780→        : Optional.<DeclaredType>absent();
   781→  }
