   783→  /**
   784→   * Resolves a {@link VariableElement} parameter to a method or constructor based on the given
   785→   * container, or a member of a class. For parameters to a method or constructor, the variable's
   786→   * enclosing element must be a supertype of the container type. For example, given a
   787→   * {@code container} of type {@code Set<String>}, and a variable corresponding to the {@code E e}
   788→   * parameter in the {@code Set.add(E e)} method, this will return a TypeMirror for {@code String}.
   789→   */
   790→  public static TypeMirror asMemberOf(Types types, DeclaredType container,
   791→      VariableElement variable) {
   792→    if (variable.getKind().equals(ElementKind.PARAMETER)) {
   793→      ExecutableElement methodOrConstructor =
   794→          MoreElements.asExecutable(variable.getEnclosingElement());
   795→      ExecutableType resolvedMethodOrConstructor = MoreTypes.asExecutable(
   796→          types.asMemberOf(container, methodOrConstructor));
   797→      List<? extends VariableElement> parameters = methodOrConstructor.getParameters();
   798→      List<? extends TypeMirror> parameterTypes =
   799→          resolvedMethodOrConstructor.getParameterTypes();
   800→      checkState(parameters.size() == parameterTypes.size());
   801→      for (int i = 0; i < parameters.size(); i++) {
   802→        // We need to capture the parameter type of the variable we're concerned about,
   803→        // for later printing.  This is the only way to do it since we can't use
   804→        // types.asMemberOf on variables of methods.
   805→        if (parameters.get(i).equals(variable)) {
   806→          return parameterTypes.get(i);
   807→        }
   808→      }
   809→      throw new IllegalStateException("Could not find variable: " + variable);
   810→    } else {
   811→      return types.asMemberOf(container, variable);
   812→    }
   813→  }
   814→
   815→  private static class CastingTypeVisitor<T> extends SimpleTypeVisitor6<T, String> {
   816→    @Override protected T defaultAction(TypeMirror e, String label) {
   817→      throw new IllegalArgumentException(e + " does not represent a " + label);
   818→    }
   819→  }
   820→
   821→  private MoreTypes() {}
   822→}
