    29→import javax.annotation.processing.AbstractProcessor;
    30→import javax.annotation.processing.Filer;
    31→import javax.annotation.processing.RoundEnvironment;
    32→import javax.annotation.processing.SupportedOptions;
    33→import javax.lang.model.SourceVersion;
    34→import javax.lang.model.element.AnnotationMirror;
    35→import javax.lang.model.element.AnnotationValue;
    36→import javax.lang.model.element.Element;
    37→import javax.lang.model.element.ExecutableElement;
    38→import javax.lang.model.element.PackageElement;
    39→import javax.lang.model.element.TypeElement;
    40→import javax.lang.model.type.DeclaredType;
    41→import javax.lang.model.util.Types;
    42→import javax.tools.Diagnostic.Kind;
    43→import javax.tools.FileObject;
    44→import javax.tools.StandardLocation;
    45→
    46→import com.google.auto.service.AutoService;
    47→import com.google.common.collect.HashMultimap;
    48→import com.google.common.collect.ImmutableSet;
    49→import com.google.common.collect.Multimap;
    50→import com.google.common.collect.Sets;
    51→
    52→/**
    53→ * Processes {@link AutoService} annotations and generates the service provider
    54→ * configuration files described in {@link java.util.ServiceLoader}.
    55→ * <p>
    56→ * Processor Options:<ul>
    57→ *   <li>debug - turns on debug statements</li>
    58→ * </ul>
    59→ */
    60→@SupportedOptions({ "debug", "verify" })
    61→public class AutoServiceProcessor extends AbstractProcessor {
    62→
    63→  /**
    64→   * Maps the class names of service provider interfaces to the
    65→   * class names of the concrete classes which implement them.
    66→   * <p>
    67→   * For example,
    68→   *   {@code "com.google.apphosting.LocalRpcService" ->
    69→   *   "com.google.apphosting.datastore.LocalDatastoreService"}
    70→   */
    71→  private Multimap<String, String> providers = HashMultimap.create();
    72→
    73→  @Override
    74→  public ImmutableSet<String> getSupportedAnnotationTypes() {
    75→    return ImmutableSet.of(AutoService.class.getName());
    76→  }
    77→
    78→  @Override
    79→  public SourceVersion getSupportedSourceVersion() {
    80→    return SourceVersion.latestSupported();
    81→  }
    82→
    83→  /**
    84→   * <ol>
    85→   *  <li> For each class annotated with {@link AutoService}<ul>
    86→   *      <li> Verify the {@link AutoService} interface value is correct
    87→   *      <li> Categorize the class by its service interface
    88→   *      </ul>
    89→   *
    90→   *  <li> For each {@link AutoService} interface <ul>
    91→   *       <li> Create a file named {@code META-INF/services/<interface>}
    92→   *       <li> For each {@link AutoService} annotated class for this interface <ul>
    93→   *           <li> Create an entry in the file
    94→   *           </ul>
    95→   *       </ul>
    96→   * </ol>
    97→   */
    98→  @Override
    99→  public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
   100→    try {
   101→      return processImpl(annotations, roundEnv);
   102→    } catch (Exception e) {
   103→      // We don't allow exceptions of any kind to propagate to the compiler
   104→      StringWriter writer = new StringWriter();
   105→      e.printStackTrace(new PrintWriter(writer));
   106→      fatalError(writer.toString());
   107→      return true;
   108→    }
   109→  }
   110→
   111→  private boolean processImpl(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
   112→    if (roundEnv.processingOver()) {
   113→      generateConfigFiles();
   114→    } else {
   115→      processAnnotations(annotations, roundEnv);
   116→    }
   117→
   118→    return true;
   119→  }
   120→
   121→  private void processAnnotations(Set<? extends TypeElement> annotations,
   122→      RoundEnvironment roundEnv) {
   123→
   124→    Set<? extends Element> elements = roundEnv.getElementsAnnotatedWith(AutoService.class);
   125→
   126→    log(annotations.toString());
   127→    log(elements.toString());
   128→
   129→    for (Element e : elements) {
   130→      // TODO(gak): check for error trees?
   131→      TypeElement providerImplementer = (TypeElement) e;
   132→      AnnotationMirror providerAnnotation = getAnnotationMirror(e, AutoService.class).get();
   133→      DeclaredType providerInterface = getProviderInterface(providerAnnotation);
   134→      TypeElement providerType = (TypeElement) providerInterface.asElement();
   135→
   136→      log("provider interface: " + providerType.getQualifiedName());
   137→      log("provider implementer: " + providerImplementer.getQualifiedName());
   138→
   139→      if (!checkImplementer(providerImplementer, providerType)) {
   140→        String message = "ServiceProviders must implement their service provider interface. "
   141→            + providerImplementer.getQualifiedName() + " does not implement "
   142→            + providerType.getQualifiedName();
   143→        error(message, e, providerAnnotation);
   144→      }
   145→
   146→      String providerTypeName = getBinaryName(providerType);
   147→      String providerImplementerName = getBinaryName(providerImplementer);
   148→      log("provider interface binary name: " + providerTypeName);
   149→      log("provider implementer binary name: " + providerImplementerName);
   150→
   151→      providers.put(providerTypeName, providerImplementerName);
   152→    }
   153→  }
   154→
   155→  private void generateConfigFiles() {
   156→    Filer filer = processingEnv.getFiler();
   157→
   158→    for (String providerInterface : providers.keySet()) {
   159→      String resourceFile = "META-INF/services/" + providerInterface;
   160→      log("Working on resource file: " + resourceFile);
   161→      try {
   162→        SortedSet<String> allServices = Sets.newTreeSet();
   163→        try {
   164→          // would like to be able to print the full path
   165→          // before we attempt to get the resource in case the behavior
   166→          // of filer.getResource does change to match the spec, but there's
   167→          // no good way to resolve CLASS_OUTPUT without first getting a resource.
   168→          FileObject existingFile = filer.getResource(StandardLocation.CLASS_OUTPUT, "",
   169→              resourceFile);
   170→          log("Looking for existing resource file at " + existingFile.toUri());
   171→          Set<String> oldServices = ServicesFiles.readServiceFile(existingFile.openInputStream());
   172→          log("Existing service entries: " + oldServices);
   173→          allServices.addAll(oldServices);
   174→        } catch (IOException e) {
   175→          // According to the javadoc, Filer.getResource throws an exception
   176→          // if the file doesn't already exist.  In practice this doesn't
   177→          // appear to be the case.  Filer.getResource will happily return a
   178→          // FileObject that refers to a non-existent file but will throw
   179→          // IOException if you try to open an input stream for it.
   180→          log("Resource file did not already exist.");
   181→        }
   182→
   183→        Set<String> newServices = new HashSet<String>(providers.get(providerInterface));
   184→        if (allServices.containsAll(newServices)) {
   185→          log("No new service entries being added.");
   186→          return;
   187→        }
   188→
   189→        allServices.addAll(newServices);
   190→        log("New service file contents: " + allServices);
   191→        FileObject fileObject = filer.createResource(StandardLocation.CLASS_OUTPUT, "",
   192→            resourceFile);
   193→        OutputStream out = fileObject.openOutputStream();
   194→        ServicesFiles.writeServiceFile(allServices, out);
   195→        out.close();
   196→        log("Wrote to: " + fileObject.toUri());
   197→      } catch (IOException e) {
   198→        fatalError("Unable to create " + resourceFile + ", " + e);
   199→        return;
   200→      }
   201→    }
   202→  }
   203→
   204→  /**
   205→   * Verifies {@link ServiceProvider} constraints on the concrete provider class.
   206→   * Note that these constraints are enforced at runtime via the ServiceLoader,
   207→   * we're just checking them at compile time to be extra nice to our users.
   208→   */
   209→  private boolean checkImplementer(TypeElement providerImplementer, TypeElement providerType) {
   210→
   211→    String verify = processingEnv.getOptions().get("verify");
   212→    if (verify == null || !Boolean.valueOf(verify)) {
   213→      return true;
   214→    }
   215→
   216→    // TODO: We're currently only enforcing the subtype relationship
   217→    // constraint. It would be nice to enforce them all.
   218→
   219→    Types types = processingEnv.getTypeUtils();
   220→
   221→    return types.isSubtype(providerImplementer.asType(), providerType.asType());
   222→  }
   223→
   224→  /**
   225→   * Returns the binary name of a reference type. For example,
   226→   * {@code com.google.Foo$Bar}, instead of {@code com.google.Foo.Bar}.
   227→   *
   228→   */
   229→  private String getBinaryName(TypeElement element) {
   230→    return getBinaryNameImpl(element, element.getSimpleName().toString());
   231→  }
   232→
   233→  private String getBinaryNameImpl(TypeElement element, String className) {
   234→    Element enclosingElement = element.getEnclosingElement();
   235→
   236→    if (enclosingElement instanceof PackageElement) {
   237→      PackageElement pkg = (PackageElement) enclosingElement;
   238→      if (pkg.isUnnamed()) {
   239→        return className;
   240→      }
   241→      return pkg.getQualifiedName() + "." + className;
   242→    }
   243→
   244→    TypeElement typeElement = (TypeElement) enclosingElement;
   245→    return getBinaryNameImpl(typeElement, typeElement.getSimpleName() + "$" + className);
   246→  }
   247→
   248→  private DeclaredType getProviderInterface(AnnotationMirror providerAnnotation) {
   249→
   250→    // The very simplest of way of doing this, is also unfortunately unworkable.
   251→    // We'd like to do:
   252→    //    ServiceProvider provider = e.getAnnotation(ServiceProvider.class);
   253→    //    Class<?> providerInterface = provider.value();
   254→    //
   255→    // but unfortunately we can't load the arbitrary class at annotation
   256→    // processing time. So, instead, we have to use the mirror to get at the
   257→    // value (much more painful).
   258→
   259→    Map<? extends ExecutableElement, ? extends AnnotationValue> valueIndex =
   260→        providerAnnotation.getElementValues();
   261→    log("annotation values: " + valueIndex);
   262→
   263→    AnnotationValue value = valueIndex.values().iterator().next();
   264→    return (DeclaredType) value.getValue();
   265→  }
   266→
   267→  private void log(String msg) {
   268→    if (processingEnv.getOptions().containsKey("debug")) {
   269→      processingEnv.getMessager().printMessage(Kind.NOTE, msg);
   270→    }
   271→  }
   272→
   273→  private void error(String msg, Element element, AnnotationMirror annotation) {
   274→    processingEnv.getMessager().printMessage(Kind.ERROR, msg, element, annotation);
   275→  }
   276→
   277→  private void fatalError(String msg) {
   278→    processingEnv.getMessager().printMessage(Kind.ERROR, "FATAL ERROR: " + msg);
   279→  }
   280→}
